#!/usr/bin/env python3
import sys, os, termios, tty, select, signal, shutil, struct, fcntl, json

# Color codes as observed via tmux capture (normalized)
C_RESET_FG = "\x1b[39m"
C_RESET_BG = "\x1b[49m"
C_RESET_ALL = "\x1b[0m"
C_BOLD = "\x1b[1m"
C_INVERT = "\x1b[7m"
C_KEY = "\x1b[94m"  # bright blue
C_NUM = "\x1b[96m"  # bright cyan
C_STR = "\x1b[92m"  # bright green
C_BOOL = "\x1b[93m" # bright yellow
C_NULL = "\x1b[91m" # bright red
C_GRAY = "\x1b[90m" # bright black for table view
C_CYAN_HDR = "\x1b[36m" # for key table header (not used in TUI)

def format_number(v):
    if isinstance(v, bool):
        # bool is subclass of int, handle separately
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        # use json.dumps to match nlohmann (which matches python)
        # json.dumps(-0.0) -> '-0.0', etc.
        return json.dumps(v)
    return str(v)

def clean_string(s):
    # Remove control chars except \n, keep others? Observed: \t,\r,\b,\f stripped, \n kept as break
    # We'll strip all ord<32 except \n
    out = []
    for ch in s:
        o = ord(ch)
        if ch == "\n":
            out.append(ch)
        elif o < 32:
            # strip (including \t \r \b \f \v \0)
            continue
        else:
            out.append(ch)
    return "".join(out)

class TUI:
    def __init__(self, data, fullscreen):
        self.data = data
        self.fullscreen = fullscreen
        # collapse state: dict path_tuple -> bool (True collapsed)
        # path is tuple of keys/indices from root
        self.collapsed = {}
        self.init_collapsed()
        # selection: list of paths in order, index
        self.sel_index = 0
        self.pending_g = False
        self.scroll = 0  # first visible physical line index
        self.term_w = 80
        self.term_h = 24
        self.update_term_size()
        self.refresh_selectable()

    def update_term_size(self):
        try:
            # try stdout, then stdin, then default
            for fd in [sys.stdout.fileno(), sys.stdin.fileno()]:
                try:
                    import fcntl, termios, struct
                    res = fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH", 0,0,0,0))
                    h, w, _, _ = struct.unpack("HHHH", res)
                    if w > 0 and h > 0:
                        self.term_w = w
                        self.term_h = h
                        return
                except:
                    continue
        except:
            pass
        try:
            sz = shutil.get_terminal_size()
            self.term_w = sz.columns
            self.term_h = sz.lines
        except:
            pass
        if self.term_w <= 0:
            self.term_w = 80
        if self.term_h <= 0:
            self.term_h = 24

    def is_empty_container(self, v):
        return (isinstance(v, dict) and len(v)==0) or (isinstance(v, list) and len(v)==0)

    def is_table_array(self, arr):
        return isinstance(arr, list) and len(arr) >= 2 and all(isinstance(x, dict) for x in arr)

    def init_collapsed(self):
        # traverse and set default collapsed per rules
        def rec(v, path, depth):
            if isinstance(v, dict):
                if len(v)==0:
                    return
                if depth == 0:
                    collapsed = False
                elif depth == 1:
                    collapsed = False
                else:
                    collapsed = True
