#!/usr/bin/env python3
import sys, os, termios, tty, select, shutil, struct, fcntl, json

C_RESET_FG = "\x1b[39m"
C_RESET_BG = "\x1b[49m"
C_RESET_ALL = "\x1b[0m"
C_BOLD = "\x1b[1m"
C_INVERT = "\x1b[7m"
C_KEY = "\x1b[94m"
C_NUM = "\x1b[96m"
C_STR = "\x1b[92m"
C_BOOL = "\x1b[93m"
C_NULL = "\x1b[91m"
C_GRAY = "\x1b[90m"

def format_number(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return json.dumps(v)
    return str(v)

def clean_string(s):
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=="\n":
            out.append(ch)
        elif o<32:
            continue
        else:
            out.append(ch)
    return "".join(out)

def clean_key(s):
    out=[]
    for ch in s:
        o=ord(ch)
        if o<32:
            continue
        else:
            out.append(ch)
    return "".join(out)

def escape_key(k):
    return clean_key(k)

class TUI:
    def __init__(self, data, fullscreen):
        self.data=data
        self.fullscreen=fullscreen
        self.collapsed={}
        self.init_collapsed()
        self.sel_index=0
        self.pending_g=False
        self.scroll=0
        self.term_w=80
        self.term_h=24
        self.update_term_size()
        self.refresh_selectable()
    def update_term_size(self):
        try:
            for fd in [sys.stdout.fileno(), sys.stdin.fileno()]:
                try:
                    res=fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH",0,0,0,0))
                    h,w,_,_=struct.unpack("HHHH",res)
                    if w>0 and h>0:
                        self.term_w=w
                        self.term_h=h
                        return
                except: continue
        except: pass
        try:
            sz=shutil.get_terminal_size()
            self.term_w=sz.columns
            self.term_h=sz.lines
        except: pass
        if self.term_w<=0: self.term_w=80
        if self.term_h<=0: self.term_h=24
    def is_empty_container(self,v):
        return (isinstance(v,dict) and len(v)==0) or (isinstance(v,list) and len(v)==0)
    def is_table_array(self,arr):
        return isinstance(arr,list) and len(arr)>=2 and all(isinstance(x,dict) for x in arr)
    def init_collapsed(self):
        def rec_all(v,path,depth):
            if isinstance(v,dict):
                if len(v)==0: return
                if depth==0: c=False
                elif depth==1: c=False
                else: c=True
                self.collapsed[path]=c
                for k in sorted(v.keys()):
                    rec_all(v[k],path+(k,),depth+1)
            elif isinstance(v,list):
                if len(v)==0: return
                if depth==0: c=False
                else: c=True
                self.collapsed[path]=c
                for i,elem in enumerate(v):
                    rec_all(elem,path+(i,),depth+1)
        rec_all(self.data,(),0)
    def is_collapsed(self,path):
        return self.collapsed.get(path,False)
    def refresh_selectable(self):
        lst=[]
        def rec(v,path):
            lst.append(path)
            if isinstance(v,dict):
                if len(v)==0: return
                if self.is_collapsed(path): return
                for k in sorted(v.keys()):
                    rec(v[k],path+(k,))
            elif isinstance(v,list):
                if len(v)==0: return
                if self.is_collapsed(path): return
                for i,elem in enumerate(v):
                    rec(elem,path+(i,))
        rec(self.data,())
        self.selectable=lst
        if self.sel_index>=len(lst): self.sel_index=len(lst)-1
        if self.sel_index<0: self.sel_index=0
    def get_value(self,path):
        v=self.data
        for p in path: v=v[p]
        return v
