                    return
                else:
                    lines.append({'path':path,'depth':depth,'kind':'open','bracket':'{','key':key,'is_last':is_last,'table':False})
                    keys=sorted(v.keys())
                    for idx,k in enumerate(keys):
                        last=(idx==len(keys)-1)
                        rec(v[k],path+(k,),depth+1,last,key=k)
                    lines.append({'path':path,'depth':depth,'kind':'close','bracket':'}','is_last':is_last})
